export const total = rows => rows.filter(r => !r.void).reduce((n,r) => n+r.cents,0);
export const count = rows => rows.filter(r => !r.void).length;
export const largest = rows => rows.filter(r => !r.void).reduce((n,r) => Math.max(n,r.cents),0);
